#!/usr/bin/env bash
# Rebuild the TP3 engine and refresh the derived kit/config. Safe to re-run.
#
# A fresh copy of this repository holds what cannot be fetched (the scripts, the AOT variants no
# shipped kit has, the padded config generator); everything else here is either upstream (src/, the
# nested clones) or regenerated by this script:
#   donor-kernels/   the LakyFx TP3 kernel archive, extracted
#   kit-tp3/         src/kitrepo/kit + donor variants + kit-extra, and the four RoPE tables
#   out/             the built binaries
#   model-tp3/       symlinks into the checkpoint on TrueNAS
# Not regenerated here, because they are per-host state: the rank caches (~97 GiB each, the
# tf-dsv41-rank-cache bake) and the token map it writes; see tools/ and tp3-start.sh.
#
# REBAKE=1 rebuilds kit-extra/aot from the donor kernels' source (needs a GPU and the image's
# Triton); the artifact is committed, so a normal build reuses it.
set -euo pipefail
ROOT=$(cd "$(dirname "$0")" && pwd)
SRC="$ROOT/src"
ZIG="/work/tools/zig/zig"
IMG="${IMG:-tensorfold-glm53:v0.6.0}"
MODEL="${MODEL:-/mnt/truenas/models/deepseekv41-full}"

docker run --rm --network none --memory=6g --memory-swap=6g \
  --user "$(id -u):$(id -g)" -e HOME=/tmp \
  -e ZIG_GLOBAL_CACHE_DIR=/work/.zig-global \
  -v "$ROOT:/work" -w /work/src/engine \
  --entrypoint "$ZIG" "$IMG" \
  build -Dnvcc=/usr/local/cuda/bin/nvcc -Dsm=121 -Doptimize=ReleaseFast -j1 \
  --prefix /work/out native lanes

if [ ! -d "$ROOT/donor-kernels/aot" ]; then
  mkdir -p "$ROOT/donor-kernels"
  tar xzf "$SRC/laky/tensorfold/artifacts/tensorfold-kernels.tar.gz" -C "$ROOT/donor-kernels"
fi
if [ ! -d "$ROOT/kit-tp3" ]; then
  cp -a "$SRC/kitrepo/kit" "$ROOT/kit-tp3"
fi
# the kit's four RoPE tables (1,114,112 rows each, 544 MB): the kit ships only rope.json and the
# digests, the tables are computed on the CPU from the checkpoint's config (kit/tools/make_rope.py
# checks each table's sha256 against rope.json and exits non-zero if one differs)
if [ ! -r "$ROOT/kit-tp3/rope-plain-cos.f32" ]; then
  docker run --rm --network none -v "$ROOT:/work" -v "$MODEL:$MODEL:ro" -w /work \
    --entrypoint python3 "$IMG" kit-tp3/tools/make_rope.py "$MODEL" /work/kit-tp3
fi
# the launch shapes no shipped kit recorded (a prefill's 1..RING_EXTRA-row tail chunk): committed, so a
# build reuses them; REBAKE=1 (or a missing kit-extra) recompiles them from the donor source, on the GPU
if [[ -n "${REBAKE:-}" || ! -f "$ROOT/kit-extra/aot/aot.json" ]]; then
  docker run --rm --gpus all --network none -v "$ROOT:/work" -w /work \
    --entrypoint python3 "$IMG" tools/bake_extra_aot.py kit-extra/aot
fi
python3 "$ROOT/tools/merge_aot.py" \
  "$SRC/kitrepo/kit/aot" "$ROOT/donor-kernels/aot" "$ROOT/kit-tp3/aot" "$ROOT/kit-extra/aot"

mkdir -p "$ROOT/model-tp3"
for f in "$MODEL"/*; do
  ln -sfn "$f" "$ROOT/model-tp3/$(basename "$f")"
done
rm -f "$ROOT/model-tp3/config.json"
python3 "$ROOT/tools/make_tp3_config.py" \
  "$MODEL/config.json" "$ROOT/model-tp3/config.json"
cp -f "$SRC/mia/model/chat_template.jinja" "$ROOT/model-tp3/chat_template.jinja"
echo "TP3 build + kit + padded config ready"
